package com.example.longshot;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;

public class MainActivity extends Activity {
 ArrayList<Bitmap> images=new ArrayList<>(); LinearLayout list; TextView status;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(248,249,252));getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);home();}
 TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 void home(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,32,24,20);root.setBackgroundColor(Color.rgb(248,249,252));setContentView(root);root.addView(label("长图助手",30,0xff182230));root.addView(label("把零散截图，拼成一张完整长图",16,0xff687386)); Button pick=new Button(this);pick.setText("选择截图");root.addView(pick);pick.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});status=label("选择多张同一页面的截图开始拼接",15,0xff475467);root.addView(status);list=new LinearLayout(this);list.setOrientation(1);ScrollView sc=new ScrollView(this);sc.addView(list);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button save=new Button(this);save.setText("生成并保存长图");root.addView(save);save.setOnClickListener(v->save());}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=1||c!=RESULT_OK||d==null)return;images.clear();try{if(d.getClipData()!=null){for(int n=0;n<d.getClipData().getItemCount();n++)add(d.getClipData().getItemAt(n).getUri());}else if(d.getData()!=null)add(d.getData());}catch(Exception e){} order();show();}
 void add(Uri u)throws Exception{Bitmap b=MediaStore.Images.Media.getBitmap(getContentResolver(),u);images.add(b);}
 void order(){if(images.size()<2)return;ArrayList<Bitmap> out=new ArrayList<>();out.add(images.remove(0));while(!images.isEmpty()){Bitmap prev=out.get(out.size()-1);int best=0,score=-1;for(int i=0;i<images.size();i++){int s=overlap(prev,images.get(i));if(s>score){score=s;best=i;}}out.add(images.remove(best));}images=out;}
 int overlap(Bitmap a,Bitmap b){int w=48, max=Math.min(a.getHeight(),b.getHeight())/2, best=0,bs=Integer.MAX_VALUE;for(int k=24;k<=max;k+=Math.max(8,max/20)){int err=0;for(int x=0;x<w;x+=2){int ax=x*a.getWidth()/w,bx=x*b.getWidth()/w;int p=a.getPixel(ax,a.getHeight()-k),q=b.getPixel(bx,Math.min(k/2,b.getHeight()-1));err+=Math.abs(Color.red(p)-Color.red(q))+Math.abs(Color.green(p)-Color.green(q))+Math.abs(Color.blue(p)-Color.blue(q));}if(err<bs){bs=err;best=k;}}return 100000-bs;}
 void show(){list.removeAllViews();for(int i=0;i<images.size();i++){final int ix=i;LinearLayout row=new LinearLayout(this);row.setPadding(8,8,8,8);row.setGravity(Gravity.CENTER_VERTICAL);TextView n=label(" "+(i+1)+" ",18,0xff2563eb);row.addView(n);ImageView iv=new ImageView(this);iv.setImageBitmap(images.get(i));iv.setAdjustViewBounds(true);iv.setMaxHeight(180);row.addView(iv,new LinearLayout.LayoutParams(0,180,1));Button up=new Button(this);up.setText("↑");row.addView(up);up.setOnClickListener(v->{if(ix>0)Collections.swap(images,ix,ix-1);show();});Button dn=new Button(this);dn.setText("↓");row.addView(dn);dn.setOnClickListener(v->{if(ix<images.size()-1)Collections.swap(images,ix,ix+1);show();});list.addView(row);}status.setText("共 "+images.size()+" 张 · 可用箭头调整顺序，再生成长图");}
 void save(){if(images.size()==0){status.setText("请先选择截图");return;}try{int w=images.get(0).getWidth(),h=0;ArrayList<Integer> cuts=new ArrayList<>();for(int i=0;i<images.size();i++){Bitmap b=images.get(i);int cut=i==0?0:Math.min(b.getHeight()/3,Math.max(0,overlap(images.get(i-1),b)%Math.max(1,b.getHeight()/3)));cuts.add(cut);h+=b.getHeight()-cut;}Bitmap all=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(all);int y=0;for(int i=0;i<images.size();i++){Bitmap b=images.get(i);Bitmap scaled=Bitmap.createScaledBitmap(b,w,(int)(b.getHeight()*(w/(float)b.getWidth())),true);cv.drawBitmap(scaled,0,y,null);y+=scaled.getHeight()-cuts.get(i);}String name="长图_"+System.currentTimeMillis()+".jpg";android.content.ContentValues v=new android.content.ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,name);v.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/长图助手");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);OutputStream o=getContentResolver().openOutputStream(u);all.compress(Bitmap.CompressFormat.JPEG,95,o);o.close();status.setText("已保存到相册：Pictures/长图助手");}catch(Exception e){status.setText("保存失败："+e.getMessage());}}
}